init_models();
var import_svix = __toESM(require_dist2(), 1);
var auth = new Hono2;
auth.post("/webhook", async (c) => {
  const payload = await c.req.text();
  const headers = c.req.header();
  const wh = new import_svix.Webhook(process.env.CLERK_WEBHOOK_SECRET || "");
  try {
    const event = wh.verify(payload, headers);
    switch (event.type) {
      case "user.created":
      case "user.updated": {
        const data = event.data;
        const email = data.email_addresses?.[0]?.email_address ?? "";
        const username = data.username ?? data.first_name ?? email.split("@")[0];
        await UserModel.findOneAndUpdate({ odiserId: data.id }, {
          odiserId: data.id,
          username,
          avatarUrl: data.image_url,
          isActive: true
        }, { upsert: true, new: true });
        break;
      }
      case "user.deleted": {
        const data = event.data;
        await UserModel.findOneAndUpdate({ odiserId: data.id }, { isActive: false });
        break;
      }
    }
    return c.json({ received: true });
  } catch (err) {
    console.error("[Webhook] Verification failed:", err);
    return c.json({ error: "Webhook verification failed" }, 400);
  }
});
